import com.acme.resilient.RAction;
import sailpoint.api.RequestManager;
import sailpoint.api.SailPointContext;
import sailpoint.api.TaskManager;
import sailpoint.object.*;
import sailpoint.reporting.JasperExecutor;
import sailpoint.tools.GeneralException;

QueryOptions queryOptions = new QueryOptions();
queryOptions.addFilter(Filter.eq("value", "cn=Vengerberg,ou=groups,dc=example,dc=org"));
Iterator iter = context.search(ManagedAttribute.class, queryOptions);
Map arguments = new HashMap();
arguments.put("entitlementId", iter.next().getId());
arguments.put("requester", context.getUserName());
Identity owner = context.getObjectByName(Identity.class, context.getUserName());
var requestDefinition = context.getObjectByName(RequestDefinition.class, "Delete Entitlement Request");
RequestManager.scheduleRequest(context, requestDefinition, arguments, "Delete ent", new Date(), owner);
